// AssetClient provides type-safe operations for the assets table.
type AssetClient interface {
	// --- Read Operations ---

	// Get returns a single asset by primary key.
	Get(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// GetMany returns assets matching the given filter, field selection, and sort criteria.
	// When FieldOptions includes O2M or M2M relationships, they are loaded via an
	// errgroup fan-out — in parallel over the pool, and serialized by the
	// transaction's connection reservation when ctx carries one.
	GetMany(ctx context.Context, input *GetAssetsInput, opts ...func(*CallOptions[AssetFieldOptions])) ([]*Asset, error)

	// Exists returns true if a asset with the given primary key exists.
	Exists(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[AssetFieldOptions])) (bool, error)

	// ExistsWhere returns true if any asset matches the given filter.
	ExistsWhere(ctx context.Context, filter *AssetFilter, opts ...func(*CallOptions[AssetFieldOptions])) (bool, error)

	// Count returns the number of assets matching the given filter.
	Count(ctx context.Context, filter *AssetFilter, opts ...func(*CallOptions[AssetFieldOptions])) (int64, error)

	// --- Write Operations ---

	// Create inserts a new asset and returns the created entity.
	Create(ctx context.Context, input *CreateAssetInput, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// CreateMany inserts multiple assets in batches and returns all created entities.
	// Sub-batches are not automatically rolled back on failure — wrap in a transaction for atomicity.
	CreateMany(ctx context.Context, inputs []*CreateAssetInput, opts ...func(*CallOptions[AssetFieldOptions])) ([]*Asset, error)

	// Update partially updates a asset by primary key and returns the updated entity.
	// Only fields where IsSet() is true are included in the SET clause.
	// Returns ErrNotFound if the primary key does not exist.
	Update(ctx context.Context, id uuid.UUID, input *UpdateAssetInput, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// UpdateMany updates multiple assets and returns the updated entities.
	UpdateMany(ctx context.Context, items []UpdateAssetItem, opts ...func(*CallOptions[AssetFieldOptions])) ([]*Asset, error)

	// UpdateWhere updates all assets matching the filter and returns the updated entities.
	// Idempotent — returns empty slice when no rows match.
	UpdateWhere(ctx context.Context, filter *AssetFilter, input *UpdateAssetInput, opts ...func(*CallOptions[AssetFieldOptions])) ([]*Asset, error)

	// Upsert inserts a asset or updates it on conflict and returns the resulting entity.
	Upsert(ctx context.Context, input *CreateAssetInput, target AssetConflictTarget, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// UpsertMany inserts or updates multiple assets in batches and returns all resulting entities.
	// Inputs resolving to the same conflict target are deduped, last occurrence wins.
	UpsertMany(ctx context.Context, inputs []*CreateAssetInput, target AssetConflictTarget, opts ...func(*CallOptions[AssetFieldOptions])) ([]*Asset, error)

	// CreateWithRelated creates a asset together with rows on its nested
	// relationships, in a single transaction. Nested rows are written through
	// the target table's own client, so their hooks, events, cache
	// invalidation and tenancy behave exactly as on a direct call.
	CreateWithRelated(ctx context.Context, input *CreateAssetWithRelatedInput, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// UpdateWithRelated updates a asset together with rows on its nested
	// relationships, in a single transaction. The nested blocks add `disconnect`
	// and `clear` to the create-side verbs, because the parent already exists
	// and there are rows to unlink.
	UpdateWithRelated(ctx context.Context, id uuid.UUID, input *UpdateAssetWithRelatedInput, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// UpsertWithRelated inserts or updates a asset together with rows on
	// its nested relationships, in a single transaction. It reuses the
	// update-side nested block verbatim — each verb means the same thing on
	// either branch, so one block is correct on both. `create` is not
	// idempotent: repeating an upsert that carries it inserts again.
	UpsertWithRelated(ctx context.Context, input *UpsertAssetWithRelatedInput, target AssetConflictTarget, opts ...func(*CallOptions[AssetFieldOptions])) (*Asset, error)

	// --- Hard Delete Operations ---

	// HardDelete permanently removes a asset from the database.
	// Idempotent — returns nil if the primary key does not exist.
	HardDelete(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[AssetFieldOptions])) error

	// HardDeleteMany permanently removes multiple assets from the database.
	HardDeleteMany(ctx context.Context, ids []uuid.UUID, opts ...func(*CallOptions[AssetFieldOptions])) error

	// HardDeleteWhere permanently removes all assets matching the filter.
	// Idempotent — returns nil when no rows match.
	HardDeleteWhere(ctx context.Context, filter *AssetFilter, opts ...func(*CallOptions[AssetFieldOptions])) error

	// --- Pagination Operations ---

	// Paginate returns a page of assets with total count for offset-based pagination.
	Paginate(ctx context.Context, input PaginateInput[AssetFilter], opts ...func(*CallOptions[AssetFieldOptions])) (*PaginateResult[Asset], error)

	// Connection returns a Relay-style cursor-paginated connection of assets.
	// Sort order is determined by cursor_keys — custom sorts are not supported.
	// Use Paginate for custom sort orders.
	Connection(ctx context.Context, input ConnectionInput[AssetFilter], opts ...func(*CallOptions[AssetFieldOptions])) (*Connection[Asset], error)

	// Stream returns an iterator over assets matching the filter and sort criteria.
	// Rows are yielded as the driver returns them; cache is bypassed.
	// Stream cannot load relationships.
	//
	// Stream refuses an active transaction unless CallOptions.AllowInTransaction
	// is set, and the opt-in commits the caller to issuing nothing else on that
	// txCtx: the one rule that remains the caller's — drain or close a result set
	// before issuing the next statement on that txCtx — applied to a loop whose
	// body is caller code.
	Stream(ctx context.Context, input *StreamAssetsInput, opts ...func(*CallOptions[StreamAssetFieldOptions])) iter.Seq2[*Asset, error]
}

