// ToConditions converts the filter to a slice of SQL conditions.
//
// A nil receiver contributes no conditions. Two callers depend on that. The
// *Where methods dereference their filter only here and document a nil one as
// the empty-filter case, so this is what makes ErrEmptyFilter reachable instead
// of a nil dereference. And a nil entry inside and / or is skipped rather than
// fatal, matching the "an unset member contributes no SQL" rule the
// relationship members already follow.
func (f *EventFilter) ToConditions(dialect sql.Dialect, opts ...FilterOption) []sql.Condition {
	if f == nil {
		return nil
	}

	var conds []sql.Condition

	if f.ASCIIArt != nil {
		conds = append(conds, f.ASCIIArt.Parse(dialect.QuoteIdentifier("ascii_art"), dialect)...)
	}

	if f.Action != nil {
		conds = append(conds, f.Action.Parse(dialect.QuoteIdentifier("action"), dialect)...)
	}

	if f.Address2ID != nil {
		conds = append(conds, f.Address2ID.Parse(dialect.QuoteIdentifier("address2_id"), dialect)...)
	}

	if f.Adjustment != nil {
		conds = append(conds, f.Adjustment.Parse(dialect.QuoteIdentifier("adjustment"), dialect)...)
	}

	if f.CSVData != nil {
		conds = append(conds, f.CSVData.Parse(dialect.QuoteIdentifier("csv_data"), dialect)...)
	}

	if f.FKVal != nil {
		conds = append(conds, f.FKVal.Parse(dialect.QuoteIdentifier("fk_val"), dialect)...)
	}

	if f.HTTP2Flag != nil {
		conds = append(conds, f.HTTP2Flag.Parse(dialect.QuoteIdentifier("http2_flag"), dialect)...)
	}

	if f.ID != nil {
		conds = append(conds, f.ID.Parse(dialect.QuoteIdentifier("id"), dialect)...)
	}

	if f.IOCount != nil {
		conds = append(conds, f.IOCount.Parse(dialect.QuoteIdentifier("io_count"), dialect)...)
	}

	if f.Line2ID != nil {
		conds = append(conds, f.Line2ID.Parse(dialect.QuoteIdentifier("line2_id"), dialect)...)
	}

	if f.MAC != nil {
		conds = append(conds, f.MAC.Parse(dialect.QuoteIdentifier("mac"), dialect)...)
	}

	if f.OSName != nil {
		conds = append(conds, f.OSName.Parse(dialect.QuoteIdentifier("os_name"), dialect)...)
	}

	if f.OccurredAt != nil {
		conds = append(conds, f.OccurredAt.Parse(dialect.QuoteIdentifier("occurred_at"), dialect)...)
	}

	if f.PKVal != nil {
		conds = append(conds, f.PKVal.Parse(dialect.QuoteIdentifier("pk_val"), dialect)...)
	}

	if f.ProcessedAt != nil {
		conds = append(conds, f.ProcessedAt.Parse(dialect.QuoteIdentifier("processed_at"), dialect)...)
	}

	if f.RetryCount != nil {
		conds = append(conds, f.RetryCount.Parse(dialect.QuoteIdentifier("retry_count"), dialect)...)
	}

	if f.S3URL != nil {
		conds = append(conds, f.S3URL.Parse(dialect.QuoteIdentifier("s3_url"), dialect)...)
	}

	if f.Succeeded != nil {
		conds = append(conds, f.Succeeded.Parse(dialect.QuoteIdentifier("succeeded"), dialect)...)
	}

	if f.TCPPort != nil {
		conds = append(conds, f.TCPPort.Parse(dialect.QuoteIdentifier("tcp_port"), dialect)...)
	}

	if f.UserID != nil {
		conds = append(conds, f.UserID.Parse(dialect.QuoteIdentifier("user_id"), dialect)...)
	}

	if f.Utf8Body != nil {
		conds = append(conds, f.Utf8Body.Parse(dialect.QuoteIdentifier("utf8_body"), dialect)...)
	}

	for _, sub := range f.And {
		subConds := sub.ToConditions(dialect, opts...)
		if len(subConds) > 0 {
			conds = append(conds, sql.And(subConds...))
		}
	}

	// A filter object's own fields are always conjunctive, so each or member
	// contributes sql.And of its own conditions and the members are OR-ed
	// together as ONE group condition. Appending a per-member
	// sql.Or instead hands the caller N conditions, and buildWhere joins those
	// with AND — turning or: [A, B] into A AND B, while simultaneously OR-ing a
	// single member's own fields against each other.
	//
	// The group is appended only when some member compiled to something:
	// sql.Or of nothing expands to a literal "()", which buildWhere keeps
	// because it is not the empty string, yielding invalid SQL.
	var orGroup []sql.Condition
	for _, sub := range f.Or {
		subConds := sub.ToConditions(dialect, opts...)
		if len(subConds) > 0 {
			orGroup = append(orGroup, sql.And(subConds...))
		}
	}
	if len(orGroup) > 0 {
		conds = append(conds, sql.Or(orGroup...))
	}

	return conds
}

