// filterProbeAllColumns is the column list for full-entity reads, sorted for determinism.
var filterProbeAllColumns = []string{"created_at", "doc", "flags", "id", "tags", "tags_n", "weights"}

// scanFilterProbes scans rows into FilterProbe entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanFilterProbes(rows database.Rows, columns []string) ([]*FilterProbe, error) {
	var result []*FilterProbe
	for rows.Next() {
		f := &FilterProbe{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &f.ID
			case "doc":
				targets[idx] = &f.Doc
			case "tags":
				targets[idx] = &f.Tags
			case "tags_n":
				targets[idx] = &f.TagsN
			case "flags":
				targets[idx] = &f.Flags
			case "weights":
				targets[idx] = &f.Weights
			case "created_at":
				targets[idx] = &f.CreatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan filter_probe: %w", err)
		}

		result = append(result, f)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate filter_probe rows: %w", err)
	}
	return result, nil
}

