// scanMaskedLabels scans rows into MaskedLabel entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanMaskedLabels(rows database.Rows, columns []string) ([]*MaskedLabel, error) {
	var result []*MaskedLabel
	for rows.Next() {
		m := &MaskedLabel{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &m.ID
			case "label":
				targets[idx] = &m.Label
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan masked_label: %w", err)
		}

		result = append(result, m)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate masked_label rows: %w", err)
	}
	return result, nil
}

