var numericWidthAllColumns = []string{"bigs", "created_at", "id", "ratio", "ratio_n", "ratios", "scores", "scores_n", "small", "small_n", "smalls"}

// scanNumericWidths scans rows into NumericWidth entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanNumericWidths(rows database.Rows, columns []string) ([]*NumericWidth, error) {
	var result []*NumericWidth
	for rows.Next() {
		n := &NumericWidth{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &n.ID
			case "small":
				targets[idx] = &n.Small
			case "small_n":
				targets[idx] = &n.SmallN
			case "ratio":
				targets[idx] = &n.Ratio
			case "ratio_n":
				targets[idx] = &n.RatioN
			case "smalls":
				targets[idx] = &n.Smalls
			case "scores":
				targets[idx] = &n.Scores
			case "bigs":
				targets[idx] = &n.Bigs
			case "ratios":
				targets[idx] = &n.Ratios
			case "scores_n":
				targets[idx] = &n.ScoresN
			case "created_at":
				targets[idx] = &n.CreatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan numeric_width: %w", err)
		}

		result = append(result, n)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate numeric_width rows: %w", err)
	}
	return result, nil
}

