// multiInsertAndResolveIDs performs a multi-row INSERT and resolves all generated primary keys.
func (c *numericWidthClient) multiInsertAndResolveIDs(ctx context.Context, conn database.Querier, columns []string, valueRows [][]any) ([]uuid.UUID, error) {
	query, args := sql.BuildMultiInsert(c.dialect, c.table, sql.MultiInsertOptions{
		Columns:          columns,
		ValueRows:        valueRows,
		ReturningColumns: []string{"id"},
	})

	rows, err := conn.Query(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var ids []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, fmt.Errorf("scan numeric_width id: %w", err)
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return ids, nil
}

