// UserIncrementColumn identifies a numeric column eligible for atomic increment/decrement.
type UserIncrementColumn string

const (
	UserIncrementInternalScore UserIncrementColumn = "internal_score"
)

// Increment atomically increments or decrements a numeric column on a user.
// A negative amount performs a decrement.
// Returns ErrNotFound if the primary key does not exist.
func (c *userClient) Increment(ctx context.Context, id uuid.UUID, input IncrementInput[UserIncrementColumn], opts ...func(*CallOptions[UserFieldOptions])) error {
	options := resolveCallOptions(opts)
	_, err := c.executeMutation(ctx, options.SkipHooks, &hook.MutationContext{
		Op: hook.OpIncrement, Table: TableUsers, Schema: "public",
		PK: id, Input: input, CallOptions: options,
	}, func(ctx context.Context, m *hook.MutationContext) (any, error) {
		conn := database.Conn(ctx, c.querier)
		query, args := sql.BuildIncrement(c.dialect, c.table, string(input.Column), input.Amount, []sql.Condition{
			sql.Where(c.dialect.QuoteIdentifier("id")).Eq(id),
		})

		execResult, err := conn.Exec(ctx, query, args...)
		if err != nil {
			return nil, fmt.Errorf("increment user %s: %w", input.Column, err)
		}

		count, err := execResult.RowsAffected()
		if err != nil {
			return nil, fmt.Errorf("increment user rows affected: %w", err)
		}
		if count == 0 {
			return nil, ErrNotFound
		}
		m.AffectedPKs = []any{id}
		return nil, nil
	})
	return err
}

// Exists returns true if a user with the given primary key exists.
// Soft-deleted users are excluded — a soft-deleted user returns false.
// Use ExistsWhere with Filter.DeletedAt comparator for soft-deleted rows.
func (c *userClient) Exists(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[UserFieldOptions])) (bool, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpExists, Table: TableUsers, Schema: "public",
		PK: id, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)
		conds := []sql.Condition{sql.Where(c.dialect.QuoteIdentifier("id")).Eq(id)}

		// Soft delete condition always applied — Exists checks for active rows only.
		conds = append(conds, sql.Where(c.dialect.QuoteIdentifier("deleted_at")).IsNull())

		query, args := sql.BuildExists(c.dialect, c.table, conds)

		var exists bool
		if err := conn.QueryRow(ctx, query, args...).Scan(&exists); err != nil {
			return false, fmt.Errorf("exists user: %w", err)
		}
		return exists, nil
	})
	if err != nil {
		return false, err
	}
	return result.(bool), nil
}

// ExistsWhere returns true if any user matches the given filter.
// Soft-deleted users are excluded by default. Set Filter.DeletedAt to override.
func (c *userClient) ExistsWhere(ctx context.Context, filter *UserFilter, opts ...func(*CallOptions[UserFieldOptions])) (bool, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpExists, Table: TableUsers, Schema: "public",
		Input: filter, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		var conds []sql.Condition
		if filter != nil {
			conds = filter.ToConditions(c.dialect)
		}

		// Soft delete: inject default if user didn't set the comparator
		if filter == nil || filter.DeletedAt == nil {
			conds = append(conds, sql.Where(c.dialect.QuoteIdentifier("deleted_at")).IsNull())
		}

		query, args := sql.BuildExists(c.dialect, c.table, conds)

		var exists bool
		if err := conn.QueryRow(ctx, query, args...).Scan(&exists); err != nil {
			return false, fmt.Errorf("exists user where: %w", err)
		}
		return exists, nil
	})
	if err != nil {
		return false, err
	}
	return result.(bool), nil
}

// Count returns the number of users matching the given filter.
// Soft-deleted users are excluded by default. Set Filter.DeletedAt to override.
// A nil filter counts all non-deleted users.
func (c *userClient) Count(ctx context.Context, filter *UserFilter, opts ...func(*CallOptions[UserFieldOptions])) (int64, error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpCount, Table: TableUsers, Schema: "public",
		Input: filter, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		conn := database.Conn(ctx, c.querier)

		var conds []sql.Condition
		if filter != nil {
			conds = filter.ToConditions(c.dialect)
		}

		// Soft delete: inject default if user didn't set the comparator
		if filter == nil || filter.DeletedAt == nil {
			conds = append(conds, sql.Where(c.dialect.QuoteIdentifier("deleted_at")).IsNull())
		}

		query, args := sql.BuildCount(c.dialect, c.table, conds)

		var count int64
		if err := conn.QueryRow(ctx, query, args...).Scan(&count); err != nil {
			return int64(0), fmt.Errorf("count users: %w", err)
		}
		return count, nil
	})
	if err != nil {
		return 0, err
	}
	return result.(int64), nil
}

// Paginate returns a page of users with total count for offset-based pagination.
// Soft-deleted users are excluded by default. Set Filter.DeletedAt to override.
// A nil filter paginates all non-deleted users.
func (c *userClient) Paginate(ctx context.Context, input PaginateInput[UserFilter], opts ...func(*CallOptions[UserFieldOptions])) (*PaginateResult[User], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableUsers, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[UserFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate users count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		users, err := c.GetMany(ctx, &GetUsersInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate users: %w", err)
		}

		return &PaginateResult[User]{
			Items:      users,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[User]), nil
}

// Connection returns a Relay-style cursor-paginated connection of users.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
// Soft-deleted users are excluded by default.
func (c *userClient) Connection(ctx context.Context, input ConnectionInput[UserFilter], opts ...func(*CallOptions[UserFieldOptions])) (*Connection[User], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection users: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableUsers, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[UserFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection users count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		users, err := c.GetMany(ctx, &GetUsersInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection users: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(users) > limit
		if hasMore {
			users = users[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(users)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[User], len(users))
		for i, row := range users {
			cursor, err := encodeUserCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[User]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[User]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[User]), nil
}

// encodeUserCursor encodes cursor key values as a base64 JSON string.
func encodeUserCursor(keys []string, u *User) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = u.ID
		case "email":
			out["email"] = u.Email
		case "name":
			out["name"] = u.Name
		case "metadata":
			out["metadata"] = u.Metadata
		case "is_active":
			out["is_active"] = u.IsActive
		case "password_hash":
			out["password_hash"] = u.PasswordHash
		case "new_password":
			out["new_password"] = u.NewPassword
		case "last_login_at":
			out["last_login_at"] = u.LastLoginAt
		case "internal_score":
			out["internal_score"] = u.InternalScore
		case "ip_addr":
			out["ip_addr"] = u.ClientIP
		case "created_at":
			out["created_at"] = u.CreatedAt
		case "updated_at":
			out["updated_at"] = u.UpdatedAt
		case "deleted_at":
			out["deleted_at"] = u.DeletedAt
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode user cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

