// scanWorkspaceSettings scans rows into WorkspaceSetting entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanWorkspaceSettings(rows database.Rows, columns []string) ([]*WorkspaceSetting, error) {
	var result []*WorkspaceSetting
	for rows.Next() {
		w := &WorkspaceSetting{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "workspace_id":
				targets[idx] = &w.WorkspaceID
			case "key":
				targets[idx] = &w.Key
			case "value":
				targets[idx] = &w.Value
			case "created_at":
				targets[idx] = &w.CreatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan workspace_setting: %w", err)
		}

		result = append(result, w)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate workspace_setting rows: %w", err)
	}
	return result, nil
}

